from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    """ Separate groups of balanced parentheses from a string """
    result = []
    group = ''
    stack = []

    for char in paren_string:
        if char == '(':
            stack.append(char)
            group += char
        elif char == ')':
            if stack:
                stack.pop()
                group += char
            else:
                # Ignore extra closing parenthesis
                continue
        else:
            # Ignore spaces
            continue

    # Add the last group if it's not empty and the stack is empty
    if group and not stack:
        result.append(group)

    return result

